        }
    }
}
```

### Step 2: Implement Custom Routing Logic

Your custom routing logic can run as a separate service that dynamically manages the backend nodes. This service can communicate with NGINX to update the backend configuration dynamically.

Here's an example of how you might implement this in Python:

```python
import random
import time
from threading import Thread, Lock
from typing import List

class Node:
    def __init__(self, name, capacity):
        self.name = name
        self.capacity = capacity
        self.current_load = 0
        self.overloaded = False
        self.lock = Lock()

    def reset_overload(self):
        if self.overloaded and self.current_load < self.capacity * 0.8:
            self.overloaded = False

    def update_load(self, increment):
        with self.lock:
            self.current_load += increment
            if self.current_load >= self.capacity:
                self.overloaded = True

class DynamicRouter:
    def __init__(self, nodes: List[Node]):
        self.nodes = nodes
        self.lock = Lock()
        self.health_check_interval = 5  # seconds
        self.health_check_thread = Thread(target=self.health_check_loop)
        self.health_check_thread.daemon = True
        self.health_check_thread.start()

    def health_check_loop(self):
        while True:
            time.sleep(self.health_check_interval)
            for node in self.nodes:
                node.reset_overload()

    def route_query(self, query):
        with self.lock:
            available_nodes = [node for node in self.nodes if not node.overloaded]
            if not available_nodes:
                raise Exception("All nodes are overloaded")

            # Use least_conn algorithm
            least_loaded_node = min(available_nodes, key=lambda node: node.current_load)
            least_loaded_node.update_load(1)
            return least_loaded_node

# Example usage:
nodes = [
    Node("Node 1", 1000),
    Node("Node 2", 1000),
    Node("Node 3", 1000)
]
router = DynamicRouter(nodes)

def simulate_queries():
    for _ in range(2000):
        query = "Example query"
        node = router.route_query(query)
        print(f"Query routed to {node.name}")
        time.sleep(0.001)  # Simulate query processing time

# Run the simulation
simulate_queries()
```

