import numpy as np

class Node:
    def __init__(self, id, capacity):
        self.id = id
        self.capacity = capacity
        self.load = 0

    def add_load(self, amount):
        self.load += amount
        if self.load > self.capacity:
            raise Exception(f"Node {self.id} overloaded")

class LoadBalancer:
    def __init__(self, nodes):
        self.nodes = nodes

    def distribute_load(self, amount):
        # Distribute load among nodes
        for node in self.nodes:
            node.add_load(amount / len(self.nodes))

