  const data = await client.get(key);
  if (data) {
    console.log(`Cache HIT for key: ${key}`);
    return JSON.parse(data);
  } else {
    console.log(`Cache MISS for key: ${key}`);
    return null;
  }
}

// Function to set data in cache
async function setDataInCache(key, value, ttl = 300) {
  const data = JSON.stringify(value);
  await client.set(key, data);
  await client.expire(key, ttl); // Set TTL in seconds
  console.log(`Data set in cache for key: ${key}`);
}

// Function to simulate fetching data from a database
function fetchDataFromDB(key) {
  // Simulate a database call with a delay
