    setTimeout(() => {
      resolve({ id: key, data: `Data for key ${key}` });
    }, 1000);
  });
}

// Function to get data from cache or database
async function getData(key) {
  const cachedData = await getDataFromCache(key);
  if (cachedData) {
    return cachedData;
  }

  const dbData = await fetchDataFromDB(key);
  await setDataInCache(key, dbData);

  return dbData;
}

// Example usage
