    public class CacheManager
    {
        private readonly MemoryCache _cache;
        private readonly ILogger _logger;

        public CacheManager()
        {
            _cache = MemoryCache.Default;
            _logger = new LoggerConfiguration()
                .WriteTo.Console()
                .CreateLogger();
        }

        public T Get<T>(string key)
        {
            var cachedValue = _cache.Get(key);
            if (cachedValue != null)
            {
                _logger.Information("Cache HIT for key: {Key}", key);
                return (T)cachedValue;
            }
            else
            {
                _logger.Warning("Cache MISS for key: {Key}", key);
                throw new CacheMissException($"Cache miss for key: {key}");
            }
        }

        public void Set(string key, object value, DateTimeOffset absoluteExpiration)
        {
            _cache.Add(key, value, absoluteExpiration);
            _logger.Information("Data set in cache for key: {Key}", key);
        }
    }

    public class CacheMissException : Exception
    {
        public CacheMissException(string message) : base(message) { }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var cacheManager = new CacheManager();

            try
            {
                // Simulate fetching data from a database
                var data = FetchDataFromDatabase("user_profile_123");

                // Store data in cache
                cacheManager.Set("user_profile_123", data, DateTimeOffset.UtcNow.AddMinutes(5));

                // Retrieve data from cache
                var cachedData = cacheManager.Get<Dictionary<string, string>>("user_profile_123");
                Console.WriteLine($"Cached data: {JsonConvert.SerializeObject(cachedData)}");
            }
            catch (CacheMissException ex)
            {
                Console.WriteLine($"Error: {ex.Message}");
            }
        }

        private static Dictionary<string, string> FetchDataFromDatabase(string key)
        {
            // Simulate a database call
            return new Dictionary<string, string>
            {
                { "id", key },
                { "data", $"Data for key {key}" }
            };
        }
    }
}
