```java
import net.spy.memcached.AddrUtil;
import net.spy.memcached.MemcachedClient;
import redis.clients.jedis.Jedis;

import java.io.IOException;
import java.util.concurrent.ExecutionException;

public class DistributedCache {

    private final Jedis redisClient;
    private final MemcachedClient memcachedClient;

    public DistributedCache(String redisHost, int redisPort, String memcachedHost, int memcachedPort) {
        this.redisClient = new Jedis(redisHost, redisPort);
        try {
            this.memcachedClient = new MemcachedClient(AddrUtil.getAddresses(memcachedHost + ":" + memcachedPort));
        } catch (IOException e) {
            throw new RuntimeException("Failed to connect to Memcached", e);
        }
    }

    public String get(String key) {
        // Try to get the value from Memcached first
        Object value = memcachedClient.get(key);
        if (value != null) {
            System.out.println("Cache HIT (Memcached) for key: " + key);
            return value.toString();
        }

        // Try to get the value from Redis
        value = redisClient.get(key);
        if (value != null) {
            System.out.println("Cache HIT (Redis) for key: " + key);
            try {
                // Store the value in Memcached for faster access next time
                memcachedClient.set(key, 300, value);
            } catch (InterruptedException | ExecutionException e) {
                System.err.println("Failed to set value in Memcached: " + e.getMessage());
            }
            return value;
        }

        System.out.println("Cache MISS for key: " + key);
        return null;
    }

    public void set(String key, String value, int ttl) {
        // Store the value in Memcached
        try {
            memcachedClient.set(key, ttl, value);
        } catch (InterruptedException | ExecutionException e) {
            System.err.println("Failed to set value in Memcached: " + e.getMessage());
        }

        // Store the value in Redis
        redisClient.setex(key, ttl, value);

        System.out.println("Data set in cache for key: " + key);
    }

    public void delete(String key) {
        // Delete the value from Memcached
        memcachedClient.delete(key);

        // Delete the value from Redis
        redisClient.del(key);

        System.out.println("Data deleted from cache for key: "  + key);
    }

    public static void main(String[] args) {
        DistributedCache cache = new DistributedCache("localhost", 6379, "localhost", 11211);

        // Simulate fetching data from a database
        String fetchDataFromDb(String key) {
            return "data for " + key;
        }

        // Function to get data from cache or database
        String getOrFetchData(String key) {
            String data = cache.get(key);
            if (data != null) {
                return data;
            }

            // Fetch data from the database
            data = fetchDataFromDb(key);
            cache.set(key, data, 300);  // Cache for 5 minutes
            return data;
        }

        // Example usage
        String key = "user_profile_123";
        String data = getOrFetchData(key);
        System.out.println("Fetched data: " + data);

        // Fetch the same data again to demonstrate cache hit
        String dataAgain = getOrFetchData(key);
        System.out.println("Fetched data again: " + dataAgain);
    }
}
```

### Explanation

1. **Initialization**:
   - The `DistributedCache` class initializes both a Redis client and a Memcached client.

2. **Get Operation**:
   - The `get` method first tries to retrieve the value from Memcached.
   - If not found, it attempts to retrieve the value from Redis.
   - If found in Redis, the value is also stored in Memcached for faster access next time.
   - If not found in either cache, it logs a cache miss.

3. **Set Operation**:
   - The `set` method stores the value in both Memcached and Redis.
   - An optional TTL (time-to-live) can be specified for the cache entries.

4. **Delete Operation**:
   - The `delete` method removes the value from both Memcached and Redis.

5. **Example Usage**:
   - Demonstrates fetching data from the cache or database and logging the results.
   - Fetches the same data again to demonstrate a cache hit.

